use super::*;

#[test]
fn discovery_keeps_no_command_line_of_an_unselected_process() {
    let mut collector = Collector::new();
    let config = CollectorConfig {
        root_pid: u32::MAX,
        sample_interval: None,
        external_processes: HashMap::new(),
    };
    assert!(collector.sample(&config, None).processes.is_empty());
    let pid = sysinfo::Pid::from_u32(std::process::id());
    let unselected = collector.system.process(pid).expect("discovered process");
    assert!(unselected.cmd().is_empty(), "an unselected process keeps its command line");
}

